), new_results AS (
 INSERT INTO public.issuer_earnings_results(id,ticker,fiscal_period,company_name,filing_day,source_url,verification_status,verification_notes)
 SELECT s.id,s.ticker,s.fiscal_period,s.company_name,s.filing_day,s.source_url,'partial','Source-reviewed SEC 8-K exhibit; historical partial actuals and management guidance, not consensus, not a complete 10-Q reconciliation. No publication timestamp set.'
