INSERT INTO public.issuer_earnings_metrics(result_id,metric_key,value_numeric,unit,accounting_basis,period_basis,source_url,source_excerpt,verification_status)
SELECT f.result_id,f.metric_key,f.value_numeric,f.unit,f.accounting_basis,f.period_basis,f.source_url,f.source_excerpt,'verified' FROM facts f JOIN new_results r ON r.id=f.result_id
ON CONFLICT DO NOTHING RETURNING result_id,metric_key;
